  constructor(
    private propertyService: PropertyService,
    private router: Router
  ) {
    // 🔄 Inicializar observables
    this.featuredProperties$ = this.propertyService.getFeaturedProperties();
  }

  ngOnInit(): void {
    this.loadFeaturedProperties();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  /**
   * 🔄 Cargar propiedades destacadas
   */
  private loadFeaturedProperties(): void {
    this.isLoading = true;
    
    this.featuredProperties$
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (properties) => {
          this.isLoading = false;
          console.log('✅ Propiedades destacadas cargadas:', properties.length);
        },
        error: (error) => {
          this.isLoading = false;
          console.error('❌ Error cargando propiedades:', error);
        }
      });
  }

  /**
   * 🔍 Manejar envío del formulario de búsqueda
   */
  onSearchSubmit(form: any): void {
    if (form.valid) {
      this.onSearch(this.searchData);
    } else {
      this.searchError = 'Por favor completa todos los campos requeridos';
    }
  }

  /**
   * 🔍 Manejar búsqueda - VERSIÓN SIMPLIFICADA
   */
  onSearch(searchParams: SearchParams): void {
    // ✅ Validación básica
    if (!searchParams.destination) {
      this.searchError = 'Por favor selecciona un destino';
      return;
    }

    if (!searchParams.checkIn || !searchParams.checkOut) {
      this.searchError = 'Por favor selecciona las fechas de tu estadía';
      return;
    }

    // ✅ Limpiar errores
    this.searchError = null;

    // ✅ Navegar a resultados con parámetros
    this.router.navigate(['/search'], { 
      queryParams: {
        destination: searchParams.destination,
        checkIn: searchParams.checkIn,
        checkOut: searchParams.checkOut,
        guests: searchParams.guests
      }
    });

    // 📊 Analytics/tracking (opcional)
    console.log('🔍 Búsqueda realizada:', searchParams);
  }

  /**
   * 🏠 Ver detalles de una propiedad específica
   */
  viewPropertyDetails(propertyId: string): void {
    // 📊 Registrar visualización
    this.propertyService.incrementPropertyViews(propertyId)
      .pipe(takeUntil(this.destroy$))
      .subscribe();

    // 🧭 Navegar a detalles
    this.router.navigate(['/property', propertyId]);
  }

  /**
   * ❤️ Toggle favorito desde la página principal
   */
  toggleFavorite(propertyId: string, event: Event): void {
    event.stopPropagation(); // Evitar navegación
    
    this.propertyService.toggleFavorite(propertyId)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (isFavorite) => {
          console.log(`${isFavorite ? '❤️' : '🤍'} Propiedad ${propertyId}`);
        },
        error: (error) => {
          console.error('❌ Error al actualizar favorito:', error);
        }
      });
  }

  /**
   * 🚀 Acciones rápidas para sugerencias
   */
  searchDestination(destination: string): void {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    
    const dayAfter = new Date();
    dayAfter.setDate(dayAfter.getDate() + 3);

    const searchParams: SearchParams = {
      destination,
      checkIn: tomorrow.toISOString().split('T')[0],
      checkOut: dayAfter.toISOString().split('T')[0],
      guests: 2
    };

    this.onSearch(searchParams);
  }

  /**
   * 🏷️ Buscar por tipo de experiencia
   */
  searchByExperience(experience: string): void {
    this.router.navigate(['/search'], { 
      queryParams: {
        experience,
        guests: 2
      }
    });
  }

